class ProductDetailsModel {  ProductDetailsModel({    required this.id,    required this.name,    required this.slug,    required this.categoryId,    required this.description,    required this.additionalInfo,    required this.price,    required this.discountPrice,    required this.dimensions,    required this.featured,    required this.popular,    required this.status,    required this.quantity,    required this.createdAt,    required this.updatedAt,    required this.images,    required this.colors,    required this.sizes,    required this.materials,    required this.reviews,    required this.primaryImage,  });  final int id;  final String name;  final String slug;  final int categoryId;  final String description;  final String additionalInfo;  final String price;  final String discountPrice;  final String dimensions;  final int featured;  final int popular;  final int status;  final int quantity;  final DateTime? createdAt;  final DateTime? updatedAt;  final List<Image> images;  final List<Color> colors;  final List<Size> sizes;  final List<Material> materials;  final List<dynamic> reviews;  final Image? primaryImage;  factory ProductDetailsModel.fromJson(Map<String, dynamic> json){    return ProductDetailsModel(      id: json["id"] ?? 0,      name: json["name"] ?? "",      slug: json["slug"] ?? "",      categoryId: json["category_id"] ?? 0,      description: json["description"] ?? "",      additionalInfo: json["additional_info"] ?? "",      price: json["price"] ?? "",      discountPrice: json["discount_price"] ?? "",      dimensions: json["dimensions"] ?? "",      featured: json["featured"] ?? 0,      popular: json["popular"] ?? 0,      status: json["status"] ?? 0,      quantity: json["quantity"] ?? 0,      createdAt: DateTime.tryParse(json["created_at"] ?? ""),      updatedAt: DateTime.tryParse(json["updated_at"] ?? ""),      images: json["images"] == null ? [] : List<Image>.from(json["images"]!.map((x) => Image.fromJson(x))),      colors: json["colors"] == null ? [] : List<Color>.from(json["colors"]!.map((x) => Color.fromJson(x))),      sizes: json["sizes"] == null ? [] : List<Size>.from(json["sizes"]!.map((x) => Size.fromJson(x))),      materials: json["materials"] == null ? [] : List<Material>.from(json["materials"]!.map((x) => Material.fromJson(x))),      reviews: json["reviews"] == null ? [] : List<dynamic>.from(json["reviews"]!.map((x) => x)),      primaryImage: json["primary_image"] == null ? null : Image.fromJson(json["primary_image"]),    );  }  Map<String, dynamic> toJson() => {    "id": id,    "name": name,    "slug": slug,    "category_id": categoryId,    "description": description,    "additional_info": additionalInfo,    "price": price,    "discount_price": discountPrice,    "dimensions": dimensions,    "featured": featured,    "popular": popular,    "status": status,    "quantity": quantity,    "created_at": createdAt?.toIso8601String(),    "updated_at": updatedAt?.toIso8601String(),    "images": images.map((x) => x.toJson()).toList(),    "colors": colors.map((x) => x.toJson()).toList(),    "sizes": sizes.map((x) => x.toJson()).toList(),    "materials": materials.map((x) => x.toJson()).toList(),    "reviews": reviews.map((x) => x).toList(),    "primary_image": primaryImage?.toJson(),  };}class Color {  Color({    required this.id,    required this.name,    required this.code,    required this.createdAt,    required this.updatedAt,    required this.pivot,  });  final int id;  final String name;  final String code;  final DateTime? createdAt;  final DateTime? updatedAt;  final ColorPivot? pivot;  factory Color.fromJson(Map<String, dynamic> json){    return Color(      id: json["id"] ?? 0,      name: json["name"] ?? "",      code: json["code"] ?? "",      createdAt: DateTime.tryParse(json["created_at"] ?? ""),      updatedAt: DateTime.tryParse(json["updated_at"] ?? ""),      pivot: json["pivot"] == null ? null : ColorPivot.fromJson(json["pivot"]),    );  }  Map<String, dynamic> toJson() => {    "id": id,    "name": name,    "code": code,    "created_at": createdAt?.toIso8601String(),    "updated_at": updatedAt?.toIso8601String(),    "pivot": pivot?.toJson(),  };}class ColorPivot {  ColorPivot({    required this.productId,    required this.colorId,  });  final int productId;  final int colorId;  factory ColorPivot.fromJson(Map<String, dynamic> json){    return ColorPivot(      productId: json["product_id"] ?? 0,      colorId: json["color_id"] ?? 0,    );  }  Map<String, dynamic> toJson() => {    "product_id": productId,    "color_id": colorId,  };}class Image {  Image({    required this.id,    required this.productId,    required this.image,    required this.isPrimary,    required this.createdAt,    required this.updatedAt,    required this.imageUrl,  });  final int id;  final int productId;  final String image;  final int isPrimary;  final DateTime? createdAt;  final DateTime? updatedAt;  final String imageUrl;  factory Image.fromJson(Map<String, dynamic> json){    return Image(      id: json["id"] ?? 0,      productId: json["product_id"] ?? 0,      image: json["image"] ?? "",      isPrimary: json["is_primary"] ?? 0,      createdAt: DateTime.tryParse(json["created_at"] ?? ""),      updatedAt: DateTime.tryParse(json["updated_at"] ?? ""),      imageUrl: json["image_url"] ?? "",    );  }  Map<String, dynamic> toJson() => {    "id": id,    "product_id": productId,    "image": image,    "is_primary": isPrimary,    "created_at": createdAt?.toIso8601String(),    "updated_at": updatedAt?.toIso8601String(),    "image_url": imageUrl,  };}class Material {  Material({    required this.id,    required this.name,    required this.createdAt,    required this.updatedAt,    required this.pivot,  });  final int id;  final String name;  final dynamic createdAt;  final dynamic updatedAt;  final MaterialPivot? pivot;  factory Material.fromJson(Map<String, dynamic> json){    return Material(      id: json["id"] ?? 0,      name: json["name"] ?? "",      createdAt: json["created_at"],      updatedAt: json["updated_at"],      pivot: json["pivot"] == null ? null : MaterialPivot.fromJson(json["pivot"]),    );  }  Map<String, dynamic> toJson() => {    "id": id,    "name": name,    "created_at": createdAt,    "updated_at": updatedAt,    "pivot": pivot?.toJson(),  };}class MaterialPivot {  MaterialPivot({    required this.productId,    required this.materialId,  });  final int productId;  final int materialId;  factory MaterialPivot.fromJson(Map<String, dynamic> json){    return MaterialPivot(      productId: json["product_id"] ?? 0,      materialId: json["material_id"] ?? 0,    );  }  Map<String, dynamic> toJson() => {    "product_id": productId,    "material_id": materialId,  };}class Size {  Size({    required this.id,    required this.name,    required this.code,    required this.createdAt,    required this.updatedAt,    required this.pivot,  });  final int id;  final String name;  final String code;  final DateTime? createdAt;  final DateTime? updatedAt;  final SizePivot? pivot;  factory Size.fromJson(Map<String, dynamic> json){    return Size(      id: json["id"] ?? 0,      name: json["name"] ?? "",      code: json["code"] ?? "",      createdAt: DateTime.tryParse(json["created_at"] ?? ""),      updatedAt: DateTime.tryParse(json["updated_at"] ?? ""),      pivot: json["pivot"] == null ? null : SizePivot.fromJson(json["pivot"]),    );  }  Map<String, dynamic> toJson() => {    "id": id,    "name": name,    "code": code,    "created_at": createdAt?.toIso8601String(),    "updated_at": updatedAt?.toIso8601String(),    "pivot": pivot?.toJson(),  };}class SizePivot {  SizePivot({    required this.productId,    required this.sizeId,  });  final int productId;  final int sizeId;  factory SizePivot.fromJson(Map<String, dynamic> json){    return SizePivot(      productId: json["product_id"] ?? 0,      sizeId: json["size_id"] ?? 0,    );  }  Map<String, dynamic> toJson() => {    "product_id": productId,    "size_id": sizeId,  };}